// What ships inside the app (spec 024): the tunes of the first levels with their answer and clip, so a new learner plays
// at once, offline. Generated by scripts/build-shipped-tunes.ts from the server's library; these tests keep the copy honest.
import { readFileSync } from 'fs';
import { join } from 'path';
import { LOCAL_ANSWER_MAX_LEVEL } from '../../../server/src/game/config';
import { TUNES } from '../../../server/src/tunes/library.data';
import { parseNotes } from '../../../server/src/tunes/notes';
import { SHIPPED_HASHES, SHIPPED_TUNES } from '../../../src/services/tunes/shippedTunes';

const first = TUNES.filter((t) => t.rank <= LOCAL_ANSWER_MAX_LEVEL);

describe('shipped tunes', () => {
  it('are exactly the tunes of the first levels', () => {
    expect(SHIPPED_TUNES.map((t) => t.id).sort()).toEqual(first.map((t) => t.id).sort());
    expect(SHIPPED_TUNES.length).toBeGreaterThanOrEqual(20);
  });

  it('carry the answer and the rhythm of their tune, and nothing is out of date', () => {
    for (const t of SHIPPED_TUNES) {
      const lib = TUNES.find((x) => x.id === t.id)!;
      const notes = parseNotes(lib.notes)!;
      expect({ id: t.id, answer: t.answer }).toEqual({
        id: t.id,
        answer: notes.map((n) => n.midi),
      });
      expect(t.beats).toEqual(notes.map((n) => n.beats));
      expect(t.phrases).toEqual([...lib.phrases]);
      expect(t.tempoBpm).toBe(lib.tempoBpm);
      expect(t.rank).toBe(lib.rank);
    }
  });

  it('each have a clip inside the app, hashed, and nowhere to download it from', () => {
    for (const t of SHIPPED_TUNES) {
      expect(t.audio.url).toBeNull();
      expect(t.audio.sha256).toMatch(/^[0-9a-f]{64}$/);
      expect(SHIPPED_HASHES.get(t.id)).toBe(t.audio.sha256);
    }
  });

  it('are the clips the audio registry requires (Metro bundles only those), plus the first melody’s opening', () => {
    const registry = readFileSync(
      join(__dirname, '../../../src/services/audio/bundled.ts'),
      'utf8',
    );
    const required = [
      ...registry.matchAll(
        /^\s+([a-z0-9]+): require\('\.\.\/\.\.\/\.\.\/assets\/app\/audio\/melodies\//gm,
      ),
    ].map((m) => m[1]);
    expect(required.sort()).toEqual([...SHIPPED_TUNES.map((t) => t.id), 'fifthfirst'].sort());
  });
});
